-- Apply using migration owner. Runtime roles must never own these tables or BYPASSRLS.
begin;
do $$ begin if not exists(select from pg_roles where rolname='agency_intake') then create role agency_intake nologin noinherit; end if; end $$;
create table public.agencies (id uuid primary key default gen_random_uuid(), name text not null);
create table public.owner_bootstrap(agency_id uuid primary key references public.agencies,email text not null unique,expires_at timestamptz not null,consumed_at timestamptz,consumed_by uuid references auth.users);
create table public.memberships (agency_id uuid not null references public.agencies, user_id uuid not null references auth.users, email text not null, role text not null check(role in ('owner','admin','agent','manager')), status text not null default 'active' check(status in ('active','disabled')), verified boolean not null default false, primary key(agency_id,user_id));
create table public.invitations(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies,email text not null,role text not null check(role in ('admin','agent')),status text not null default 'pending' check(status in ('pending','accepted','revoked')),expires_at timestamptz not null default now()+interval '7 days',created_by uuid not null references auth.users,accepted_by uuid references auth.users,created_at timestamptz not null default now());
create unique index invitation_pending on public.invitations(agency_id,lower(email)) where status='pending';
create table public.leads(id uuid primary key default gen_random_uuid(),agency_id uuid not null references public.agencies,name text not null,email text not null default '',phone text not null default '',state text not null check(length(state)=2),product text not null check(product in ('term_life','whole_life','final_expense','mortgage_protection','retirement','veteran_benefits','unsure')),carrier text,age_range text,budget text,interest text,preferred_contact text,follow_up_at timestamptz,do_not_contact boolean not null default false, intent text not null check(intent in ('quote','appointment')),status text not null default 'new' check(status in ('new','contacted','qualified','application','sold','closed','archived')),assigned_to uuid,source_path text not null,utm jsonb not null default '{}',fictional boolean not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(agency_id,id),foreign key(agency_id,assigned_to) references public.memberships(agency_id,user_id));
create index leads_agency_created on public.leads(agency_id,created_at desc);
create index leads_assignee on public.leads(agency_id,assigned_to);
create table public.consent_events(id uuid primary key default gen_random_uuid(),agency_id uuid not null,lead_id uuid not null,version text not null,contact boolean not null check(contact),marketing boolean not null,contact_text text not null,marketing_text text not null,created_at timestamptz not null default now(),foreign key(agency_id,lead_id) references public.leads(agency_id,id));
create table public.lead_events(id uuid primary key default gen_random_uuid(),agency_id uuid not null,lead_id uuid not null,actor_id uuid references auth.users,event text not null,detail jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(agency_id,lead_id) references public.leads(agency_id,id));
create table public.agent_eligibility(id uuid primary key default gen_random_uuid(),agency_id uuid not null,user_id uuid not null,state text not null,product text not null,carrier text not null,active boolean not null default false,verified boolean not null default false,license_expires_at timestamptz not null,verified_until timestamptz not null,verification_reference text not null,foreign key(agency_id,user_id) references public.memberships(agency_id,user_id));
create table public.notification_outbox(id uuid primary key default gen_random_uuid(),agency_id uuid not null,lead_id uuid not null,event text not null,status text not null default 'pending' check(status in ('pending','leased','sent','failed')),attempts integer not null default 0,available_at timestamptz not null default now(),lease_until timestamptz,created_at timestamptz not null default now(),foreign key(agency_id,lead_id) references public.leads(agency_id,id));
create table public.intake_requests(agency_id uuid not null references public.agencies,key uuid not null,payload_hash text not null,lead_id uuid not null,created_at timestamptz not null default now(),primary key(agency_id,key),foreign key(agency_id,lead_id) references public.leads(agency_id,id));
create table public.rate_buckets(bucket text primary key,hits integer not null,expires_at timestamptz not null);
-- Helpers read authoritative memberships rather than caller-editable JWT metadata.
create function public.agency_admin(a uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where agency_id=a and user_id=auth.uid() and status='active' and role in ('owner','admin')); $$;
create function public.can_read_lead(a uuid,assigned uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where agency_id=a and user_id=auth.uid() and status='active' and (role in ('owner','admin') or (role='agent' and user_id=assigned))); $$;
create function public.visible_lead(a uuid,l uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.leads where agency_id=a and id=l and public.can_read_lead(agency_id,assigned_to)); $$;
revoke all on function public.agency_admin(uuid),public.can_read_lead(uuid,uuid),public.visible_lead(uuid,uuid) from public;
grant execute on function public.agency_admin(uuid),public.can_read_lead(uuid,uuid),public.visible_lead(uuid,uuid) to authenticated;
do $$ declare t text; begin foreach t in array array['owner_bootstrap','agencies','memberships','invitations','leads','consent_events','lead_events','agent_eligibility','notification_outbox','intake_requests','rate_buckets'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.agencies,public.memberships,public.invitations,public.leads,public.consent_events,public.lead_events,public.agent_eligibility to authenticated;
create policy agency_select on public.agencies for select to authenticated using(exists(select 1 from public.memberships where agency_id=id and user_id=auth.uid() and status='active' and role in ('owner','admin','agent')));
create policy membership_select on public.memberships for select to authenticated using((user_id=auth.uid() and status='active') or public.agency_admin(agency_id));
create policy invitation_select on public.invitations for select to authenticated using(public.agency_admin(agency_id));
create policy lead_select on public.leads for select to authenticated using(public.can_read_lead(agency_id,assigned_to));
create policy consent_select on public.consent_events for select to authenticated using(public.visible_lead(agency_id,lead_id));
create policy event_select on public.lead_events for select to authenticated using(public.visible_lead(agency_id,lead_id));
create policy eligibility_select on public.agent_eligibility for select to authenticated using(public.agency_admin(agency_id));
-- No direct writes to leads: every mutation has its own reviewed transaction.
create function public.update_lead_status(p_lead uuid,p_status text) returns public.leads language plpgsql security definer set search_path='' as $$ declare l public.leads; begin select * into l from public.leads where id=p_lead for update; if not found or not public.can_read_lead(l.agency_id,l.assigned_to) then raise exception 'NOT_FOUND' using errcode='42501'; end if; if p_status not in ('new','contacted','qualified','application','sold','closed','archived') then raise exception 'INVALID_STATUS' using errcode='22023'; end if; update public.leads set status=p_status,updated_at=now() where id=l.id returning * into l; insert into public.lead_events(agency_id,lead_id,actor_id,event,detail) values(l.agency_id,l.id,auth.uid(),'status_changed',jsonb_build_object('status',p_status)); return l; end $$;
create function public.assign_lead(p_lead uuid,p_agent uuid,p_expected uuid,p_reason text) returns public.leads language plpgsql security definer set search_path='' as $$ declare l public.leads; m public.memberships; begin select * into l from public.leads where id=p_lead for update; if not found or not public.agency_admin(l.agency_id) then raise exception 'NOT_FOUND' using errcode='42501'; end if; if l.assigned_to is distinct from p_expected then raise exception 'OWNERSHIP_CONFLICT' using errcode='40001'; end if; if p_reason is null or length(trim(p_reason))<3 or length(p_reason)>500 then raise exception 'INVALID_REASON' using errcode='22023'; end if; select * into m from public.memberships where agency_id=l.agency_id and user_id=p_agent for share; if not found or m.status<>'active' or not m.verified or m.role<>'agent' then raise exception 'AGENT_INELIGIBLE' using errcode='22023'; end if; if l.carrier is null then raise exception 'CARRIER_UNVERIFIED' using errcode='22023'; end if; perform 1 from public.agent_eligibility e where e.agency_id=l.agency_id and e.user_id=p_agent and e.state=l.state and e.product=l.product and e.carrier=l.carrier and e.active and e.verified and e.license_expires_at>now() and e.verified_until>now() and length(e.verification_reference)>0 for share; if not found then raise exception 'AGENT_INELIGIBLE' using errcode='22023'; end if; update public.leads set assigned_to=p_agent,updated_at=now() where id=l.id returning * into l; insert into public.lead_events(agency_id,lead_id,actor_id,event,detail) values(l.agency_id,l.id,auth.uid(),'assigned',jsonb_build_object('agentId',p_agent,'reason',p_reason)); insert into public.notification_outbox(agency_id,lead_id,event) values(l.agency_id,l.id,'assigned'); return l; end $$;
create function public.create_invitation(p_agency uuid,p_email text,p_role text) returns public.invitations language plpgsql security definer set search_path='' as $$ declare i public.invitations; begin if not public.agency_admin(p_agency) then raise exception 'FORBIDDEN' using errcode='42501'; end if; if p_role not in ('admin','agent') or length(p_email)>254 or position('@' in p_email)<2 then raise exception 'INVALID_INVITATION' using errcode='22023'; end if; if p_role='admin' and not exists(select 1 from public.memberships where agency_id=p_agency and user_id=auth.uid() and role='owner' and status='active') then raise exception 'FORBIDDEN' using errcode='42501'; end if; insert into public.invitations(agency_id,email,role,created_by) values(p_agency,lower(trim(p_email)),p_role,auth.uid()) returning * into i; return i; end $$;
-- Only Supabase Auth can call this hook. Exact invitation, never domain trust.
create function public.before_user_created(event jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ begin if event->'user'->'app_metadata'->>'provider' is distinct from 'google' or (not exists(select 1 from public.invitations where lower(email)=lower(event->'user'->>'email') and status='pending' and expires_at>now()) and not exists(select 1 from public.owner_bootstrap where lower(email)=lower(event->'user'->>'email') and consumed_at is null and expires_at>now())) then return jsonb_build_object('error',jsonb_build_object('http_code',403,'message','Invitation required')); end if; return '{}'::jsonb; end $$;
create function public.accept_invitation() returns public.memberships language plpgsql security definer set search_path='' as $$ declare u auth.users; i public.invitations; m public.memberships; b public.owner_bootstrap; begin select * into u from auth.users where id=auth.uid(); if not found or u.email_confirmed_at is null or u.raw_app_meta_data->>'provider' is distinct from 'google' then raise exception 'INVITATION_REQUIRED' using errcode='42501'; end if; select * into m from public.memberships where user_id=u.id and status='active'; if found then return m; end if; if exists(select 1 from public.memberships where user_id=u.id) then raise exception 'MEMBERSHIP_DISABLED' using errcode='42501'; end if; select * into b from public.owner_bootstrap where lower(email)=lower(u.email) and consumed_at is null and expires_at>now() for update; if found then if exists(select 1 from public.memberships where agency_id=b.agency_id and role='owner') then raise exception 'OWNER_EXISTS' using errcode='42501'; end if; insert into public.memberships(agency_id,user_id,email,role,status,verified) values(b.agency_id,u.id,u.email,'owner','active',true) returning * into m; update public.owner_bootstrap set consumed_at=now(),consumed_by=u.id where agency_id=b.agency_id; return m; end if; select * into i from public.invitations where lower(email)=lower(u.email) and status='pending' and expires_at>now() order by created_at limit 1 for update; if not found then raise exception 'INVITATION_REQUIRED' using errcode='42501'; end if; insert into public.memberships(agency_id,user_id,email,role,status,verified) values(i.agency_id,u.id,u.email,i.role,'active',true) returning * into m; update public.invitations set status='accepted',accepted_by=u.id where id=i.id; return m; end $$;
create function public.submit_intake(p_agency uuid,p_key uuid,p_hash text,p_bucket text,p_payload jsonb,p_contact_text text,p_marketing_text text) returns jsonb language plpgsql security definer set search_path='' as $$ declare existing public.intake_requests; l public.leads; hits integer; begin
 perform pg_advisory_xact_lock(hashtextextended(p_agency::text||p_key::text,0));
 select * into existing from public.intake_requests where agency_id=p_agency and key=p_key; if found then if existing.payload_hash<>p_hash then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505'; end if; return jsonb_build_object('receipt',existing.lead_id,'replayed',true); end if;
 insert into public.rate_buckets(bucket,hits,expires_at) values(p_bucket,1,now()+interval '10 minutes') on conflict(bucket) do update set hits=case when public.rate_buckets.expires_at<now() then 1 else public.rate_buckets.hits+1 end,expires_at=case when public.rate_buckets.expires_at<now() then now()+interval '10 minutes' else public.rate_buckets.expires_at end returning rate_buckets.hits into hits;
 if hits>5 then raise exception 'RATE_LIMITED' using errcode='54000'; end if;
 if (p_payload->'consent'->>'contact')::boolean is distinct from true or p_payload->'consent'->>'version' is distinct from '2026-10-10.v1' then raise exception 'INVALID_CONSENT' using errcode='22023'; end if;
 insert into public.leads(agency_id,name,email,phone,state,product,intent,source_path,utm,fictional,age_range,budget,interest,preferred_contact) values(p_agency,p_payload->>'name',p_payload->>'email',p_payload->>'phone',p_payload->>'state',p_payload->>'product',p_payload->>'intent',p_payload->>'sourcePath',coalesce(p_payload->'utm','{}'),(p_payload->>'fictional')::boolean,p_payload->>'ageRange',p_payload->>'budget',p_payload->>'interest',p_payload->>'preferredContact') returning * into l;
 insert into public.consent_events(agency_id,lead_id,version,contact,marketing,contact_text,marketing_text) values(p_agency,l.id,p_payload->'consent'->>'version',true,(p_payload->'consent'->>'marketing')::boolean,p_contact_text,p_marketing_text);
 insert into public.lead_events(agency_id,lead_id,event) values(p_agency,l.id,'created');
 insert into public.notification_outbox(agency_id,lead_id,event) values(p_agency,l.id,'intake');
 insert into public.intake_requests(agency_id,key,payload_hash,lead_id) values(p_agency,p_key,p_hash,l.id);
 return jsonb_build_object('receipt',l.id,'replayed',false); end $$;
create function public.update_lead(p_lead uuid,p_patch jsonb) returns public.leads language plpgsql security definer set search_path='' as $$ declare l public.leads; begin select * into l from public.leads where id=p_lead for update; if not found or not public.can_read_lead(l.agency_id,l.assigned_to) then raise exception 'NOT_FOUND' using errcode='42501'; end if; if exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('status','follow_up_at','do_not_contact')) then raise exception 'INVALID_PATCH' using errcode='22023'; end if; update public.leads set status=coalesce(p_patch->>'status',status),follow_up_at=case when p_patch?'follow_up_at' then (p_patch->>'follow_up_at')::timestamptz else follow_up_at end,do_not_contact=case when p_patch?'do_not_contact' then (p_patch->>'do_not_contact')::boolean else do_not_contact end,updated_at=now() where id=l.id returning * into l; insert into public.lead_events(agency_id,lead_id,actor_id,event,detail) values(l.agency_id,l.id,auth.uid(),'updated',p_patch); return l; end $$;
create function public.add_lead_note(p_lead uuid,p_body text) returns public.lead_events language plpgsql security definer set search_path='' as $$ declare l public.leads; e public.lead_events; begin select * into l from public.leads where id=p_lead for share; if not found or not public.can_read_lead(l.agency_id,l.assigned_to) then raise exception 'NOT_FOUND' using errcode='42501'; end if; if p_body is null or length(trim(p_body))<1 or length(p_body)>2000 then raise exception 'INVALID_NOTE' using errcode='22023'; end if; insert into public.lead_events(agency_id,lead_id,actor_id,event,detail) values(l.agency_id,l.id,auth.uid(),'note',jsonb_build_object('body',p_body)) returning * into e; return e; end $$;
revoke all on function public.update_lead(uuid,jsonb),public.add_lead_note(uuid,text) from public;
grant execute on function public.update_lead(uuid,jsonb),public.add_lead_note(uuid,text) to authenticated;
revoke all on function public.update_lead_status(uuid,text),public.assign_lead(uuid,uuid,uuid,text),public.create_invitation(uuid,text,text),public.accept_invitation(),public.before_user_created(jsonb),public.submit_intake(uuid,uuid,text,text,jsonb,text,text) from public;
grant execute on function public.update_lead_status(uuid,text),public.assign_lead(uuid,uuid,uuid,text),public.create_invitation(uuid,text,text),public.accept_invitation() to authenticated;
grant usage on schema public to agency_intake;
grant execute on function public.submit_intake(uuid,uuid,text,text,jsonb,text,text) to agency_intake;
grant execute on function public.before_user_created(jsonb) to supabase_auth_admin;
commit;
